#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

# 默认写 ECS 生产 env；本地演练可用 ENV_FILE_OVERRIDE 覆盖。
ENV_FILE="${ENV_FILE_OVERRIDE:-$ENV_FILE}"
if [[ "$ENV_FILE" == ".env" ]]; then
  ENV_FILE="/opt/yunhefc/.env"
fi
if [[ -n "${BASH_SOURCE[0]:-}" && -f "${BASH_SOURCE[0]}" ]]; then
  REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
else
  REPO_ROOT="$(pwd)"
fi

PUBLIC_DOMAIN=""
MP_VERIFY_TOKEN=""
WECHAT_APP_ID=""
WECHAT_APP_SECRET=""
ECS_PUBLIC_IP=""

compose_current() {
  local registry namespace tag
  registry=$(sed -n 's/^ACR_REGISTRY=//p' /opt/yunhefc/env/acr.env | tail -1)
  namespace=$(sed -n 's/^ACR_NAMESPACE=//p' /opt/yunhefc/env/acr.env | tail -1)
  tag=$(sed -n 's/^IMAGE_TAG=//p' /opt/yunhefc/current/release.env | tail -1)
  IMAGE_REGISTRY="${registry%/}/$namespace" IMAGE_TAG="$tag" \
    docker compose --project-name yunhefc --env-file "$ENV_FILE" \
      -f /opt/yunhefc/current/docker-compose.yml \
      -f /opt/yunhefc/current/docker-compose.prod.yml "$@"
}

banner "云河FC — 微信登录生产启用与真机验收"

stage "生产信息确认"
say "本向导只改微信相关配置，不动数据库与业务数据。"
note "env 目标：$ENV_FILE"
warn "请在 ECS 上运行本脚本（需要写 $ENV_FILE 与操作 docker）；浏览器步骤在你的电脑上完成。"
ask PUBLIC_DOMAIN "生产域名（回车默认 www.yunhefc.com）："
PUBLIC_DOMAIN="${PUBLIC_DOMAIN:-www.yunhefc.com}"
CALLBACK_URL="https://${PUBLIC_DOMAIN}/api/v1/c/auth/wechat/callback"
note "回调地址：$CALLBACK_URL"
note "该地址必须与公众号「网页授权域名」登记的域名一致。"
pause

stage "公众号 — 基本配置（AppID / AppSecret / IP 白名单）"
open_url "https://mp.weixin.qq.com/"
if [[ ! -t 1 ]]; then
  note "无图形界面时，请在你自己的电脑上打开上述地址。"
fi
step "登录公众号后台 → 设置与开发 → 基本配置"
step "复制 AppID（公开）"
ask WECHAT_APP_ID "AppID："
step "点击 AppSecret 的「重置」或「查看」，复制密钥（只显示一次；重置会让旧密钥立即失效）"
ask_secret WECHAT_APP_SECRET "AppSecret（输入不可见）："
step "在同一页把 ECS 公网 IP 加入 IP 白名单（网页授权换取 token 需要）"
ask ECS_PUBLIC_IP "ECS 公网 IP（可留空，稍后手动加）："
if [[ -n "$ECS_PUBLIC_IP" ]]; then
  note "请确认 IP 白名单已包含：$ECS_PUBLIC_IP"
fi
pause

stage "公众号 — 网页授权域名与验证文件"
open_url "https://mp.weixin.qq.com/"
step "设置与开发 → 公众号设置 → 功能设置 → 网页授权域名"
step "下载 MP_verify_XXXX.txt；文件名里的 XXXX 就是验证 token"
ask MP_VERIFY_TOKEN "MP_verify token（不含 MP_verify_ 前缀与 .txt）："
MP_VERIFY_TOKEN="${MP_VERIFY_TOKEN#MP_verify_}"
MP_VERIFY_TOKEN="${MP_VERIFY_TOKEN%.txt}"
if [[ -z "$MP_VERIFY_TOKEN" ]]; then
  warn "验证 token 不能为空；退出。"
  exit 1
fi
VERIFY_FILE="$REPO_ROOT/frontend/apps/web/public/MP_verify_${MP_VERIFY_TOKEN}.txt"
printf '%s' "$MP_VERIFY_TOKEN" > "$VERIFY_FILE"
note "已写入仓库：$VERIFY_FILE"
note "该文件需随下一次 main 部署固化；容器重建后临时副本会丢失。"
NGINX_CONTAINER=$(docker ps --filter "name=nginx" --format '{{.Names}}' 2>/dev/null | head -n1 || true)
if [[ -n "$NGINX_CONTAINER" ]] && confirm "把验证文件复制到运行中的 nginx（$NGINX_CONTAINER）立即生效？"; then
  if docker cp "$VERIFY_FILE" "$NGINX_CONTAINER:/usr/share/nginx/html/MP_verify_${MP_VERIFY_TOKEN}.txt"; then
    note "已复制到容器；重建 nginx 后需重新部署仓库版本。"
  else
    warn "docker cp 失败；请检查 docker 权限或手动上传验证文件。"
  fi
fi
if curl -fsS "https://${PUBLIC_DOMAIN}/MP_verify_${MP_VERIFY_TOKEN}.txt" 2>/dev/null | grep -Fqx "$MP_VERIFY_TOKEN"; then
  note "✓ 验证文件可访问"
else
  warn "验证文件暂不可访问；确认 nginx 就绪后在 MP 页面点击保存前手动检查。"
fi
step "回到 MP 页面，填写 ${PUBLIC_DOMAIN}（不带 https:// 或路径），点击「保存」"
pause

stage "写入 ECS 生产 env"
if [[ -z "$WECHAT_APP_ID" || -z "$WECHAT_APP_SECRET" ]]; then
  warn "AppID / AppSecret 不能为空；prod 会 fail-fast。退出后重跑。"
  exit 1
fi
if [[ -f "$ENV_FILE" ]]; then
  BACKUP="$ENV_FILE.bak.$(date +%Y%m%d%H%M%S)"
  cp "$ENV_FILE" "$BACKUP"
  note "已备份：$BACKUP"
else
  warn "$ENV_FILE 不存在；将新建（请确认其他运行时变量已就位）。"
fi
write_env WECHAT_ENABLED "true"
write_env WECHAT_MODE "real"
write_env WECHAT_APP_ID "$WECHAT_APP_ID"
write_env WECHAT_APP_SECRET "$WECHAT_APP_SECRET"
write_env WECHAT_CALLBACK_URL "$CALLBACK_URL"
write_env WECHAT_ALLOWED_REDIRECT_PREFIXES "/"
write_env WECHAT_REQUIRE_UA "true"
chmod 600 "$ENV_FILE" 2>/dev/null || warn "无法 chmod 600 $ENV_FILE"
note "只 upsert 微信相关键，其余运行时变量保持不变。"

stage "重启 backend 使配置生效"
if [[ -f /opt/yunhefc/current/docker-compose.yml && -f /opt/yunhefc/env/acr.env ]]; then
  say "只重建 backend，不动 nginx（保留验证文件）。"
  if confirm "现在执行 compose up -d --no-deps backend？"; then
    if ! compose_current up -d --no-deps backend; then
      warn "compose 重建失败；未继续等待 readiness。"
    fi
    say "等待 readiness…"
    health_code=""
    for _ in $(seq 1 60); do
      health_code=$(curl -s -o /dev/null -w '%{http_code}' "https://${PUBLIC_DOMAIN}/actuator/health" 2>/dev/null || true)
      if [[ "$health_code" == "200" ]]; then
        break
      fi
      sleep 2
    done
    if [[ "$health_code" == "200" ]]; then
      note "✓ readiness OK"
    else
      warn "readiness 未通过；查看 backend 日志后再继续。"
    fi
  fi
else
  warn "未找到 /opt/yunhefc/current 或 acr.env；请在 ECS 上按 RUNBOOK 手动重建 backend。"
fi
pause

stage "生产预检"
say "检查 HTTPS 首页、验证文件、回调 302 与 readiness。"
home_code=$(curl -s -o /dev/null -w '%{http_code}' "https://${PUBLIC_DOMAIN}/" 2>/dev/null || true)
note "首页 HTTP：$home_code（期望 200/301）"
if curl -fsS "https://${PUBLIC_DOMAIN}/MP_verify_${MP_VERIFY_TOKEN}.txt" 2>/dev/null | grep -Fqx "$MP_VERIFY_TOKEN"; then
  note "✓ 验证文件可访问"
else
  warn "验证文件不可访问"
fi
callback_headers=$(curl -s -o /dev/null -D - -H 'Accept: text/html' \
  "https://${PUBLIC_DOMAIN}/api/v1/c/auth/wechat/callback?code=invalid&state=invalid" 2>/dev/null || true)
callback_status=$(printf '%s' "$callback_headers" | awk 'toupper($1) ~ /^HTTP\// {code=$2} END {print code}')
callback_location=$(printf '%s' "$callback_headers" | grep -i '^location:' | tail -n1 | tr -d '\r')
note "回调 HTTP：${callback_status:-未知}（期望 302）"
[[ -n "$callback_location" ]] && note "$callback_location"
health=$(curl -s "https://${PUBLIC_DOMAIN}/actuator/health" 2>/dev/null || true)
note "health：${health:-不可访问}"
pause

stage "微信真机验收"
open_url "https://${PUBLIC_DOMAIN}/login"
step "用手机微信打开或扫码上述地址（必须是微信内置浏览器）"
step "1) 手机号+密码登录 → 个人中心 → 绑定微信 → 显示已绑定"
step "2) 退出或换设备 → 点「微信登录」授权 → 直接登录并恢复身份"
step "3) 未注册手机号首次微信授权 → 进入「绑定手机号」表单 → 填写手机号/验证码/姓名/位置"
step "4) 管理员在 B07 审核通过后可报名；审核前写操作应被拒绝"
step "5) 管理员解绑微信后重新授权，应回到绑定手机号页"
step "6) 检查没有 error= 回调失败页；日志无 openid/secret 明文"
if confirm "以上真机步骤全部通过？"; then
  note "✓ 微信登录生产验收完成"
else
  warn "未通过：记录失败步骤与 error 码，按 RUNBOOK §3.7 排查后重跑本向导。"
  SKIPPED+=("微信真机验收未通过")
fi

finish
